<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow, Piet Mondrian, 1930</title>
<meta name="description" content="Piet Mondrian, 1930, De Stijl: an asymmetric balance of a few primary-colour blocks.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Jost:wght@400;500;800&display=swap" rel="stylesheet">
<style>
:root{--red:#d40920;--blue:#1356a2;--yellow:#fac901;--black:#111;--white:#f6f4ee;--line:14px}
*{box-sizing:border-box;margin:0}
body{background:var(--black);color:var(--black);font-family:Jost,"Helvetica Neue",Arial,sans-serif;font-size:1.1rem;line-height:1.5}
main{display:grid;gap:var(--line);background:var(--black);min-height:100vh;padding:var(--line);
 grid-template-columns:1fr 1.1fr 1.6fr;
 grid-template-areas:
  "title title red"
  "facts why red"
  "blue why yellow"
  "blue src src"}
main>*{padding:clamp(1rem,2.5vw,2rem);background:var(--white)}
.red{grid-area:red;background:var(--red);min-height:16rem}
.blue{grid-area:blue;background:var(--blue);min-height:9rem}
.yellow{grid-area:yellow;background:var(--yellow);min-height:9rem}
.title{grid-area:title}
.facts{grid-area:facts}
.why{grid-area:why}
.src{grid-area:src}
h1{font-weight:800;font-size:clamp(2rem,5vw,4rem);line-height:1;text-transform:uppercase;letter-spacing:-.01em}
h1 span{display:block;font-weight:400;font-size:.35em;letter-spacing:.12em;margin-top:1rem}
h2{font-size:.8rem;letter-spacing:.2em;text-transform:uppercase;font-weight:800;margin-bottom:.8rem;border-bottom:var(--line) solid var(--black);padding-bottom:.4rem}
dl{display:grid;grid-template-columns:auto 1fr;gap:.35rem 1rem}
dt{font-weight:800}dd{margin:0}
ul{padding-left:1.1rem}
a.cta{display:inline-block;margin-top:.6rem;background:var(--black);color:var(--white);padding:.8rem 1.2rem;font-weight:800;text-decoration:none;letter-spacing:.08em;text-transform:uppercase}
a.cta:hover,a.cta:focus-visible{background:var(--red);outline:3px solid var(--black);outline-offset:3px}
@media(max-width:760px){
 main{grid-template-columns:1fr 1fr;grid-template-areas:"title title" "red red" "facts facts" "blue yellow" "why why" "src src"}
}
@media(prefers-reduced-motion:no-preference){.red,.blue,.yellow{animation:in .9s ease-out both}.blue{animation-delay:.15s}.yellow{animation-delay:.3s}
 @keyframes in{from{transform:scale(.92);opacity:0}}}
</style>
</head>
